            aOrbiterG = (((aWandererG + RotL64(aIngress, 50U)) + RotL64(aCarry, 23U)) + 0x7F7A81FCFB4C10CFULL) + aTwistOrbiterAssignSaltF[(((255U - aIndex) + 175U)) & S_SALT1];
