            //
            aOrbiterI = ((aWandererK + RotL64(aScatter, 3U)) + RotL64(aCarry, 19U)) + 0xC5A47909C72AD48AULL;
            aOrbiterB = (aWandererC + RotL64(aCross, 51U)) + 0xF23D51F0EACD6613ULL;
            aOrbiterJ = ((aWandererJ + RotL64(aPrevious, 13U)) + 0xDE9ECA23C956646DULL) + aTwistOrbiterAssignSaltD[((aIndex + 134U)) & S_SALT1];
            aOrbiterH = ((aWandererH + RotL64(aIngress, 29U)) + RotL64(aCarry, 53U)) + 0x5B74EB38C5295808ULL;
            aOrbiterA = ((aWandererF + RotL64(aPrevious, 19U)) + RotL64(aCarry, 41U)) + 0x9951DDFC2CAA603FULL;
            aOrbiterG = ((aWandererA + RotL64(aCross, 58U)) + 0x6A16A8B0707BC57FULL) + aTwistOrbiterAssignSaltA[(((255U - aIndex) + 23U)) & S_SALT1];
            aOrbiterD = (aWandererE + RotL64(aIngress, 39U)) + 0x04691C81D6BC9EAFULL;
            //
            aOrbiterI = (aOrbiterI + aOrbiterB) + 0x7BA86C746FC1983EULL;
            aOrbiterJ = ((aOrbiterJ ^ aOrbiterI) ^ 0xECB8097A4D17C984ULL) ^ aTwistOrbiterUpdateSaltB[((aIndex + 64U)) & S_SALT1];
            aOrbiterJ = RotL64((aOrbiterJ * 0xA2EC9D120A824303ULL), 27U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterI) + 0x80E4B7A7CD9A32ADULL;
            aOrbiterA = (aOrbiterA ^ aOrbiterH) ^ 0xE5E8F6FB9D054A60ULL;
            aOrbiterA = RotL64((aOrbiterA * 0x866C21C308B6CF9BULL), 57U);
