            aOrbiterB = RotL64((aOrbiterB * 0x24E9E9EFBCD5436DULL), 21U);
            //
            aOrbiterD = ((aOrbiterD + aOrbiterG) + 0x47BE5CA06355BE8BULL) + aTwistOrbiterUpdateSaltC[((aIndex + 136U)) & S_SALT1];
