            //
            aOrbiterB = (aOrbiterB + aOrbiterD) + 0x0853F633DD096837ULL;
            aOrbiterH = (aOrbiterH ^ aOrbiterB) ^ 0x3053731A8E7AD6DEULL;
            aOrbiterH = RotL64((aOrbiterH * 0x977B3F684CD1464DULL), 11U);
            //
            aOrbiterA = ((aOrbiterA + aOrbiterJ) + 0x2B7BC17272B457C5ULL) + aTwistOrbiterUpdateSaltE[((aIndex + 96U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterA) ^ 0x03991FCC7F77666FULL;
            aOrbiterD = RotL64((aOrbiterD * 0x52FB103826E25501ULL), 41U);
            //
            aOrbiterJ = (aOrbiterJ + aOrbiterH) + 0x3DFA13CD3E32E412ULL;
            aOrbiterG = ((aOrbiterG ^ aOrbiterJ) ^ 0xAE54CD036B69F89FULL) ^ aTwistOrbiterUpdateSaltD[(((255U - aIndex) + 44U)) & S_SALT1];
