            aWandererA = aWandererA + ((RotL64(aScatter, 43U) + RotL64(aOrbiterB, 29U)) + aOrbiterH);
            aWandererB = aWandererB ^ ((RotL64(aIngress, 58U) + aOrbiterE) + RotL64(aOrbiterD, 39U));
            aWandererD = aWandererD + (((RotL64(aPrevious, 47U) + aOrbiterD) + RotL64(aOrbiterI, 5U)) + aTwistWandererUpdateSaltD[(((255U - aIndex) + 42U)) & S_SALT1]);
            aWandererI = aWandererI ^ ((RotL64(aCross, 23U) + aOrbiterK) + RotL64(aOrbiterH, 52U));
