            aOrbiterF = (aOrbiterF + aOrbiterB) + 0x168817A617BCA0BAULL;
            aOrbiterH = ((aOrbiterH ^ aOrbiterF) ^ 0x18F3B854BD1ABDB8ULL) ^ aKeyRotateAOrbiterUpdateSaltB[(((255U - aIndex) + 95U)) & S_SALT1];
            aOrbiterH = RotL64((aOrbiterH * 0xBDD9A972FB54C84DULL), 21U);
            //
            aOrbiterH = (aOrbiterH + aOrbiterK) + 0x30EA1A9E30DB41A4ULL;
