            aOrbiterC = RotL64((aOrbiterC * 0xB2603ACDB7B0C86BULL), 5U);
            //
            aOrbiterB = ((aOrbiterB + aOrbiterJ) + 0x70AD4948C9DE13B8ULL) + aKeyRotateAOrbiterUpdateSaltE[((aIndex + 68U)) & S_SALT1];
            aOrbiterK = (aOrbiterK ^ aOrbiterB) ^ 0xF660EFC508F1B375ULL;
            aOrbiterK = RotL64((aOrbiterK * 0xCCE580F258CBDDB1ULL), 35U);
            //
            aOrbiterI = ((aOrbiterI + aOrbiterH) + 0x6308908F945662FEULL) + aKeyRotateAOrbiterUpdateSaltA[((aIndex + 29U)) & S_SALT1];
            aOrbiterD = (aOrbiterD ^ aOrbiterI) ^ 0x4D158564A2931147ULL;
