            //
            aOrbiterJ = (aOrbiterJ + aOrbiterF) + 0x7E43D1BA3306C13CULL;
            aOrbiterI = ((aOrbiterI ^ aOrbiterJ) ^ 0x0DC77D5DAF90B85FULL) ^ aKeyRotateAOrbiterUpdateSaltD[((aIndex + 153U)) & S_SALT1];
